L000274	\begin{equation}\label{decoupledH-phi4}
L000275	    \mathcal{H}_{\rm quartic}(p,\tau)=p\coth\frac{\pi p}{\sqrt{2}}+\frac{2}{\pi}\left(\tau\tanh\frac{\tau}{\sqrt{2}}-\sqrt{2}\right)\ .
