L000471	        \left[
L000472	        (2-k_{\rm dw^+}^2)K(k_{\rm dw^+})-4E(k_{\rm dw^+})
L000473	        -\frac{3\pi^2}{2K(k_{\rm dw^+})}
L000474	        \right]\ .
L000475	    \end{aligned}
L000476	\end{equation}
L000477	For $\mu\to0^+$, this yields
L000478	\begin{equation}\label{eq:dwplus-exp}
L000479	    \begin{aligned}
L000480	        \omega_{\rm dw^+}(\mu)
L000481	        &=\frac{2\pi}{\log\frac{4}{g_c\mu}}
L000482	        -\frac{6\pi g_c\mu}{\log\frac{4}{g_c\mu}}
L000483	        +\mathcal{O}\left(\frac{\mu}{\log^2\mu}\right)\ ,\\
L000484	        \eta_{\rm dw^+}(\mu)
L000485	        &=\frac{1}{4\pi}\log\frac{4}{g_c\mu}
L000486	        -\frac{2}{\pi}
L000487	        -\frac{3\pi}{2\log\frac{4}{g_c\mu}}
L000488	        +\mathcal{O}(\mu\log\mu)\ .
L000489	    \end{aligned}
L000490	\end{equation}
L000491	For completeness, we provide more precise expansions for the quartic case
L000492	\begin{equation}\label{eq:quartic-WKB-near-crit}
L000493	    \begin{aligned}
L000494	        \omega_{\rm quartic}(\mu)
L000495	        &=\frac{\pi \sqrt2}{\log \frac{4}{|g_c|\mu}}
L000496	        -\frac{3\pi\sqrt{2}|g_c|\mu}{\log\frac{4}{|g_c|\mu}}
L000497	        +\mathcal{O}\left(\frac{\mu}{\log^2\mu}\right),\\
L000498	        \eta_{\rm quartic}(\mu)
L000499	        &=\frac{1}{2\sqrt2\pi}\log\frac{4}{|g_c|\mu}
L000500	        -\frac{2\sqrt{2}}{\pi}-\frac{\pi}{\sqrt{2}\log\frac{4}{|g_c|\mu}}
L000501	        +\mathcal{O}(\mu\log\mu)\ .
L000502	    \end{aligned}
L000503	\end{equation}
L000504	Here we also present more precise values of $\Delta_{{\rm max}}=\eta_{\rm max}$ for all cases
L000505	\begin{align}
L000506	    \label{eq:nmax-phi4}
L000507	    n^{\rm quartic}_\text{max}&\approx\frac{1}{4\pi^2}\log^2\frac{4}{e^2|g_c|\mu} -\frac{1}{3}\ ,\\
L000508	    \label{eq:nmax-phi3}
L000509	    n^{\rm cubic}_{\rm max}&\approx\frac{1}{8\pi^2}\log^2\frac{8}{e^2g^2_c\mu}-\frac{5}{12}\ ,\\
L000510	    \label{eq:nmax-dw-negative}
L000511	    n^{\rm dw^-}_{\rm max}&\approx
L000512	    \frac{1}{2\pi^2}\log^2\frac{4}{g_c|\mu|}-\frac{1}{3}\ ,\\
L000513	    \label{eq:nmax-dw-positive}
L000514	    n^{\rm dw^+}_{\rm max}&\approx
L000515	    \frac{1}{8\pi^2}\log^2\frac{4}{e^2g_c\mu}-\frac{1}{6}\ .
L000516	\end{align}
