L000518	\section{Numerical diagonalization}\label{app:numerics}
L000519	We start with the MO equation \eqref{MO-eq} for the quartic potential \eqref{eq:quartpot}.
L000520	We rescale the $x \to  a x$ coordinate and introduce $k^2 =\frac{g a^4}{\mu_F}=\frac{a^2}{b^2}\leq 1$ such that
L000521	\begin{equation}
L000522	    \Delta\,\Phi(x)= \frac{1}{\sqrt{1-k^2}}{\fint_{-1}^{1}\limits \frac{\d y}{\pi}\frac{\sqrt{(1-y^2)(1+k^2y^2)}}{(x-y)^2}} \left( \Phi(x) - \Phi(y) \right)\ .
L000523	\end{equation}
L000524	We discretize the integrand on a grid
L000525	\begin{equation}
L000526	    x_m=\cos\phi_m\ , \quad\phi_m=\frac{m\pi}{M+1}\ , \quad m = 1, 2, \dots, M\ .
L000527	\end{equation}
L000528	Then the MO equation is
L000529	\begin{align}
L000530	    \Delta_n\,\phi_n(x_j) &= K_{jm} \phi_n(x_m)\ ,\\
L000531	    K_{jm} &= -\frac{1}{M+1} \frac{\sin^2 \phi_m}{\sqrt{1-k^2}}\frac{ \sqrt{1 + k^2 \cos^2 \phi_m}}{(\cos \phi_j - \cos \phi_m)^2}, \qquad j \ne m\ ,\\
L000532	    K_{jj} &= -\sum_{m \ne j} K_{jm}\ .
L000533	\end{align}
L000534	For numerical stability, it is more convenient to conjugate this operator $K \to H =  D K D^{-1}$, where $H$ is a Hermitian operator and $D$ is the diagonal matrix $D_{jm} = \delta_{jm} {\sin \phi_m (1+k^2 \cos^2 \phi_m) ^{1/4}}$.
L000535	\begin{equation}
L000536	    H_{jm}= -\frac{1}{M+1} \frac{\sin \phi_j \sin \phi_m }{\sqrt{1-k^2}}\frac{ (1 + k^2 \cos^2 \phi_j)^{1/4} (1 + k^2 \cos^2 \phi_m)^{1/4} }{(\cos \phi_j - \cos \phi_m)^2}\ , \quad j \ne m\ ,
L000537	\end{equation}
L000538	The low-lying spectrum can be efficiently computed using the Lanczos algorithm.
L000539	We then performed a large $M$ extrapolation for each eigenvalue that was obtained, e.g., we fit a function
L000540	\begin{equation}
L000541	    \Delta^{M}_n = \Delta_n + \frac{1}{M} a_n + \frac{1}{M^2} b_n + \frac{1}{M^3} c_n + \frac{1}{M^4} d_n\ .
L000542	\end{equation}
L000543	The results of this large $M$ extrapolation are reported in Figure \ref{fig:spectrum}. For this plot we used values of $M$ ranging from $M= \{25000, 26000,27000, \dots, 40000\}$.
L000544	Note that the eigenfunctions are highly oscillatory for large energies and therefore, to probe the ``long string'' states, one has to consider rather large values of $M$ to accurately find these states for small $\mu$.
L000545	
L000546	For the cubic potential, we used the same method but with $M = 40000$ to 46000 with increments of 2000. We performed a large $M$ extrapolation using the ansatz $\Delta_n^M = \Delta_n + a_n/M + b_b/M^2$. We used these slightly different parameters since at $\mu = 10^{-14}$ the value of $n_\text{max}$ is appreciably lower in the cubic than in the quartic; hence the eigenvalues at $n\gtrsim 36$ for the cubic are not well-converged for $M \lesssim 4 \times 10^4$.
L000547	
