L000573	\section{Effect of the linear dilaton background}\label{app:Dilaton-back}
L000574	Let us consider the world sheet action of 2D string theory, which includes the linear dilaton background,
L000575	\begin{equation}
L000576	    S\left[\phi\right]=\int d^2 \sigma  \sqrt{-\operatorname{det} g}\left[
L000577	    \frac{1}{4 \pi \alpha^{\prime}}
L000578	    g^{a b} (-\partial_a X^0 \partial_b X^0 +\partial_a \phi \partial_b \phi) + \frac{1}{4 \pi} Q \phi R(g)- \mu e^{2\phi/\sqrt{\alpha'}}\right]\ .
L000579	\end{equation}
L000580	With these conventions, $c_\phi= 1+ 6\alpha' Q^2$, so for $c_\phi=25$ we should set $Q=\frac{2}{\sqrt{\alpha'}}$.
L000581	We work in the static gauge where $X^0 = \tau$ and set $\mu=0$ so that we focus on the dynamics far from the Liouville wall.
L000582	A classical solution \cite{Maldacena:2005hi} is
L000583	\begin{equation}
L000584	    \phi(\tau,\sigma)
L000585	    = \phi_0' - Q \alpha' \log \left( \cosh \frac{\tau}{\alpha' Q} + \cosh \frac{\sigma}{\alpha' Q} \right)\ .
L000586	\end{equation}
L000587	So the tip $\phi_\text{tip} = \phi(\tau,0) $ at $\sigma = 0$ moves according to
L000588	\begin{equation}
L000589	    \phi(\tau) = \phi_0 - 2 Q \alpha^{\prime}  \log \cosh (\frac{\tau}{\alpha' Q})\ .
L000590	\end{equation}
L000591	From this solution we can derive the space-time energy, which in static gauge is just $E = \frac{1}{2\pi \alpha'}\int \d \sigma $. This quantity is divergent; to regulate it we cut off the world sheet at $\phi = \phi_c$. Then the spacetime energy for the folded string is
L000592	\begin{equation}
L000593	    E = \frac{1}{\pi \alpha'}(\phi_0 - \phi_c)
L000594	    = \frac{\phi-\phi_c}{\pi \alpha^{\prime}}-\frac{Q}{\pi } \log (1-v^2)\ .
L000595	\end{equation}
L000596	Here $ v= \d \phi/ \d \tau $.
L000597	We can rewrite the Hamiltonian in canonical variables, by using the relation $v = \dot{\phi} = \partial H/\partial P$ or $\d P = \frac{1}{v} \d E$:
L000598	\begin{equation}
L000599	    P = \int \frac{1}{v} \frac{\partial E}{\partial v} \,\d v = \frac{2Q}{\pi }\int \frac{\d v}{1-v^2}  = \frac{2Q}{\pi} \text{ arctanh\,} v\ .
L000600	\end{equation}
L000601	 Thus $1 - v^2 = 1/\cosh^2\left( \frac{\pi}{2Q} P \right)$, or
L000602	\begin{equation}
L000603	    E =  \frac{\phi-\phi_c}{\pi \alpha'} +
L000604	     \frac{2Q}{\pi} \log \cosh \left(\frac{\pi}{2Q} P \right)\ .
L000605	\end{equation}
L000606	Expanding at small $P$, we get a term
L000607	\begin{equation}
L000608	    E \supset \frac{1}{2M}P^2 , \quad M = \frac{2 Q}{\pi }\ .
L000609	\end{equation}
